SELECT *, MIN(sqft) OVER (PARTITION BY region) AS region_min_sqft, AVG(sqft) OVER (PARTITION BY city) AS city_avg_sqft, RANK() OVER (PARTITION BY city ORDER BY sqft) AS sqft_rank, SUM(sqft) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, AVG(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sqft_avg_6_prior FROM stores;
